namespace Og.Core.Tests;

/// <summary>
/// Three lives have gone through this valley and no two of them were ever in it
/// on the same day. The pale stones spell TOGETHER and the woman on the hill says
/// out loud that she has never seen it happen.
///
/// You cannot schedule other people. What you can do is let a character leave
/// something behind that the next one finds without being told it is there, which
/// is the only togetherness a world of solitary lives can actually have. These
/// tests are about that mark: that it lands, that it accumulates, that it does not
/// eat the other things a room remembers, and that it outlives the person.
/// </summary>
public class LeavingAMarkTests
{
    private const string CairnHeading = "Wedged into the stones, lately:";

    private static Location Cairn(GameEngine engine) =>
        engine.World.Locations.First(location => location.Name == "The Cairn");

    private static void AtTheCairnWithASpoon(GameEngine engine, Session session)
    {
        engine.MoveTo(session, Cairn(engine).Id);
        GiveSpoon(engine, session);
    }

    private static void GiveSpoon(GameEngine engine, Session session)
    {
        if (engine.World.CreateItem("shiny spoon") is { } spoon)
        {
            session.Character.Inventory.Add(spoon);
        }
    }

    /// <summary>The lines under the cairn's heading, and nothing the room keeps after them.</summary>
    private static string[] Marks(Location cairn)
    {
        var index = cairn.Description.IndexOf(CairnHeading, StringComparison.Ordinal);

        if (index < 0)
        {
            return [];
        }

        var block = cairn.Description[(index + CairnHeading.Length)..].TrimStart('\r', '\n');

        return block.Split("\n\n")[0]
            .Split('\n', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries);
    }

    [Fact]
    public void GivingTheSpoonPutsYourNameOnTheHill()
    {
        var (engine, _) = WorldFixture.NewEngine();
        var (alice, _) = WorldFixture.Join(engine, "Alice");
        AtTheCairnWithASpoon(engine, alice);

        var cairn = engine.CurrentLocation(alice)!;

        engine.HandleInput(alice, "give spoon");

        Assert.Contains(CairnHeading, cairn.Description);
        Assert.Contains("a shiny spoon, left by Alice.", cairn.Description);
    }

    [Fact]
    public void TheHillIsStillWearingWhoeverCameBefore()
    {
        var (engine, _) = WorldFixture.NewEngine();
        var (alice, _) = WorldFixture.Join(engine, "Alice");
        AtTheCairnWithASpoon(engine, alice);

        var cairn = engine.CurrentLocation(alice)!;
        var before = cairn.Description;

        engine.HandleInput(alice, "give spoon");

        // Whoever the world file was seeded with is somebody, and they are still
        // there after the next person adds to it. A post between lives is no use
        // if every life wipes the last one off it.
        Assert.Contains("Gavin", before);
        Assert.Contains("Gavin", cairn.Description);
        Assert.Contains("Alice", cairn.Description);
    }

    [Fact]
    public void ASecondLifeReadsTheFirstOneWithoutBeingTold()
    {
        var (engine, _) = WorldFixture.NewEngine();
        var (alice, _) = WorldFixture.Join(engine, "Alice");
        AtTheCairnWithASpoon(engine, alice);
        engine.HandleInput(alice, "give spoon");

        // Alice is finished with. Bob has never heard of her and nobody tells him.
        WorldFixture.Kill(engine, alice);

        var (bob, bobSaw) = WorldFixture.Join(engine, "Bob");
        engine.MoveTo(bob, Cairn(engine).Id);

        Assert.Contains("left by Alice", bobSaw.Text);
    }

    [Fact]
    public void OnlyOneMarkPerLife()
    {
        var (engine, _) = WorldFixture.NewEngine();
        var (alice, _) = WorldFixture.Join(engine, "Alice");
        AtTheCairnWithASpoon(engine, alice);

        var cairn = engine.CurrentLocation(alice)!;

        engine.HandleInput(alice, "give spoon");
        GiveSpoon(engine, alice);
        engine.HandleInput(alice, "give spoon");

        Assert.Single(Marks(cairn).Where(line => line.Contains("Alice")));
    }

    [Fact]
    public void TheOldestNamesFadeRatherThanThePlaceBecomingALedger()
    {
        var (engine, _) = WorldFixture.NewEngine();
        var cairn = Cairn(engine);

        for (var life = 1; life <= 9; life++)
        {
            var (player, _) = WorldFixture.Join(engine, $"Life{life}");
            AtTheCairnWithASpoon(engine, player);
            engine.HandleInput(player, "give spoon");
            WorldFixture.Kill(engine, player);
        }

        Assert.Equal(6, Marks(cairn).Length);
        Assert.Contains("left by Life9.", cairn.Description);
        Assert.DoesNotContain("left by Life1.", cairn.Description);
    }

    [Fact]
    public void AGraveAndAHeapCanShareARoomWithoutEatingEachOther()
    {
        var (engine, _) = WorldFixture.NewEngine();
        var (alice, _) = WorldFixture.Join(engine, "Alice");
        AtTheCairnWithASpoon(engine, alice);

        var cairn = engine.CurrentLocation(alice)!;

        engine.HandleInput(alice, "give spoon");

        // Nothing on that hill can kill you, but a god can, and a room should not
        // lose one kind of memory to make room for the other kind.
        WorldFixture.Kill(engine, alice, "the wind");

        var (bob, _) = WorldFixture.Join(engine, "Bob");
        engine.MoveTo(bob, cairn.Id);
        GiveSpoon(engine, bob);
        engine.HandleInput(bob, "give spoon");

        Assert.Contains("a shiny spoon, left by Alice.", cairn.Description);
        Assert.Contains("a shiny spoon, left by Bob.", cairn.Description);
        Assert.Contains("Alice, killed by the wind.", cairn.Description);
        Assert.Equal(3, Marks(cairn).Length);
    }

    [Fact]
    public void TheMarkIsInTheLogUnderItsOwnName()
    {
        var (engine, events) = WorldFixture.NewEngine();
        var (alice, _) = WorldFixture.Join(engine, "Alice");
        AtTheCairnWithASpoon(engine, alice);

        engine.HandleInput(alice, "give spoon");

        var inscribed = Assert.Single(events.Events.Where(entry => entry.Type == EventType.Inscribed));
        Assert.Contains("Alice", inscribed.Payload["entry"]);
    }

    /// <summary>
    /// Two people, on two different nights, stood on that ledge and typed east.
    /// It was the most-asked question in this world and it had no answer at all.
    /// The ledge has an edge; that is a real thing to be told, and being told it
    /// is not the same as being walked off it.
    /// </summary>
    [Fact]
    public void TheLedgeAnswersTheDirectionPeopleKeptTrying()
    {
        var (engine, _) = WorldFixture.NewEngine();
        var (alice, output) = WorldFixture.Join(engine, "Alice");

        var overlook = engine.World.Locations.First(location => location.Name == "The Overlook");
        engine.MoveTo(alice, overlook.Id);
        output.Clear();

        engine.HandleInput(alice, "east");

        Assert.Contains("forty feet", output.Text);
        Assert.Equal(overlook.Id, alice.CurrentLocationId);
        Assert.False(alice.Character.IsDead);
    }

    [Fact]
    public void AndTheLongerWayOfSayingIt()
    {
        var (engine, events) = WorldFixture.NewEngine();
        var (alice, _) = WorldFixture.Join(engine, "Alice");

        var overlook = engine.World.Locations.First(location => location.Name == "The Overlook");
        engine.MoveTo(alice, overlook.Id);

        engine.HandleInput(alice, "go east");

        Assert.DoesNotContain(events.Events,
            entry => entry.Type == EventType.UnparsedCommand && entry.Payload["text"] == "go east");
    }
}

namespace Og.Core.Runtime;

public sealed record ValidationIssue(string Severity, string Message)
{
    public const string Error = "error";
    public const string Warning = "warning";

    public override string ToString() => $"[{Severity}] {Message}";
}

/// <summary>
/// Structural checks over a loaded world. Cheap enough to run on every change,
/// and needs no build.
/// </summary>
public static class WorldValidator
{
    public static IReadOnlyList<ValidationIssue> Validate(World world)
    {
        var issues = new List<ValidationIssue>();
        var ids = world.Locations.Select(location => location.Id).ToHashSet();

        if (ids.Count == 0)
        {
            issues.Add(new ValidationIssue(ValidationIssue.Error, "World has no locations."));
            return issues;
        }

        if (!ids.Contains(world.SpawnLocation))
        {
            issues.Add(new ValidationIssue(ValidationIssue.Error,
                $"Spawn location {world.SpawnLocation} does not exist."));
        }

        foreach (var location in world.Locations)
        {
            foreach (var direction in Enum.GetValues<Direction>())
            {
                var target = location.Exit(direction);

                if (target != 0 && !ids.Contains(target))
                {
                    issues.Add(new ValidationIssue(ValidationIssue.Error,
                        $"Location {location.Id} exits {direction} to {target}, which does not exist."));
                }
            }

            foreach (var interaction in location.Interactions)
            {
                if (interaction.Triggers.Length == 0)
                {
                    issues.Add(new ValidationIssue(ValidationIssue.Error,
                        $"Location {location.Id} has an interaction with no triggers."));
                }

                foreach (var action in interaction.Actions)
                {
                    ValidateAction(world, ids, location.Id, action, issues);
                }
            }
        }

        ValidateReachability(world, issues);
        return issues;
    }

    private static void ValidateAction(
        World world,
        HashSet<int> locationIds,
        int locationId,
        WorldAction action,
        List<ValidationIssue> issues)
    {
        // An action nobody implements does nothing at all, quietly, forever. The
        // world file is the only place that would ever say otherwise.
        if (!ActionKinds.All.Contains(action.Kind))
        {
            issues.Add(new ValidationIssue(ValidationIssue.Error,
                $"Location {locationId} uses '{action.AsWritten}', which is not something an "
                + $"interaction can do. It would be read and then ignored. "
                + $"What there is: {string.Join(", ", ActionKinds.All.Order())}."));
            return;
        }

        switch (action.Kind)
        {
            case ActionKind.AddItems:
            case ActionKind.RemoveItems:
                foreach (var name in action.Parameters)
                {
                    if (world.FindItemDefinition(name) is null)
                    {
                        issues.Add(new ValidationIssue(ValidationIssue.Error,
                            $"Location {locationId} references unknown item '{name}'."));
                    }
                }
                break;

            case ActionKind.ChangeLocation:
            case ActionKind.SetLocationDescription:
                if (!locationIds.Contains(action.FirstParameterAsInt))
                {
                    issues.Add(new ValidationIssue(ValidationIssue.Error,
                        $"Location {locationId} targets location {action.FirstParameterAsInt}, which does not exist."));
                }
                break;

            case ActionKind.EnableInteraction:
            case ActionKind.DisableInteraction:
                if (action.Scope == Model.Scope.World && world.FindInteraction(action.FirstParameter) is null)
                {
                    issues.Add(new ValidationIssue(ValidationIssue.Error,
                        $"Location {locationId} toggles unknown interaction '{action.FirstParameter}'."));
                }
                break;

            // A mark left for whoever comes next is worth getting right, because
            // nobody is going to be standing there to say it came out wrong: the
            // person who made it is gone by the time it is read.
            case ActionKind.Inscribe:
                if (action.Parameters.Length < 2)
                {
                    issues.Add(new ValidationIssue(ValidationIssue.Error,
                        $"Location {locationId} inscribes without both a heading and a line to write "
                        + "under it, so it would write nothing at all."));
                }
                else if (!action.Parameters[0].TrimEnd().EndsWith(':'))
                {
                    issues.Add(new ValidationIssue(ValidationIssue.Warning,
                        $"Location {locationId} inscribes under the heading '{action.Parameters[0]}', "
                        + "which does not end in a colon. The heading is found again by looking for it "
                        + "in the room's own description; one that does not read as a heading will read "
                        + "as prose, and the list under it will be hard to tell from the room."));
                }
                break;
        }
    }

    private static void ValidateReachability(World world, List<ValidationIssue> issues)
    {
        var reached = new HashSet<int>();
        var queue = new Queue<int>();
        queue.Enqueue(world.SpawnLocation);

        while (queue.Count > 0)
        {
            var id = queue.Dequeue();

            if (!reached.Add(id) || world.FindLocation(id) is not { } location)
            {
                continue;
            }

            foreach (var direction in Enum.GetValues<Direction>())
            {
                if (location.Exit(direction) is var target and > 0)
                {
                    queue.Enqueue(target);
                }
            }

            // Portals count as connectivity.
            foreach (var action in location.Interactions.SelectMany(interaction => interaction.Actions))
            {
                if (action.Kind == ActionKind.ChangeLocation)
                {
                    queue.Enqueue(action.FirstParameterAsInt);
                }
            }
        }

        foreach (var location in world.Locations.Where(candidate => !reached.Contains(candidate.Id)))
        {
            issues.Add(new ValidationIssue(ValidationIssue.Warning,
                $"Location {location.Id} ('{location.Name}') is unreachable from spawn."));
        }

        if (!world.Locations.Any(location => location.IsExit && reached.Contains(location.Id)))
        {
            issues.Add(new ValidationIssue(ValidationIssue.Warning, "No reachable exit in this world."));
        }
    }

    public static bool HasErrors(IEnumerable<ValidationIssue> issues) =>
        issues.Any(issue => issue.Severity == ValidationIssue.Error);
}

