using Og.Core.Model;

namespace Og.Core.Definitions;

public sealed class InteractionDefinition
{
    public string? InteractionId { get; set; }
    public string[] Triggers { get; set; } = [];
    public ActionDefinition[] Actions { get; set; } = [];
    public string[] If { get; set; } = [];
    public string[] IfNot { get; set; } = [];

    /// <summary>
    /// Items that must be in the player's hands for this to fire, and items that
    /// must not be.
    ///
    /// Conditions are flags: they say what has happened. These say what is being
    /// carried, which the world file had no way of asking about before, so an
    /// interaction triggered on the word "spoon" fired just as happily for
    /// somebody who did not have one — and took nothing, and gave a flask, and
    /// wrote a spoon they never owned onto the cairn under their name.
    /// </summary>
    public string[] IfCarrying { get; set; } = [];
    public string[] IfNotCarrying { get; set; } = [];

    public bool Disabled { get; set; }

    /// <summary>
    /// World: enabling or disabling affects everyone (a lever stays pulled).
    /// Player: each player has their own enabled state (a personal quest gate).
    /// </summary>
    public Scope Scope { get; set; } = Scope.World;

    /// <summary>Whether the interaction fires only once per player.</summary>
    public bool Once { get; set; }
}

using Og.Core.Definitions;
using Og.Core.Model;

namespace Og.Core.Runtime;

public sealed class Interaction
{
    public string? Id { get; }
    public string[] Triggers { get; }
    public WorldAction[] Actions { get; }
    public string[] If { get; }
    public string[] IfNot { get; }

    /// <summary>What must be in your hands, and what must not.</summary>
    public string[] IfCarrying { get; }
    public string[] IfNotCarrying { get; }

    public Scope Scope { get; }
    public bool Once { get; }

    /// <summary>World-scoped disabled state. Player-scoped state lives on the session.</summary>
    public bool DisabledForWorld { get; set; }

    public Interaction(InteractionDefinition definition)
    {
        Id = definition.InteractionId;
        Triggers = definition.Triggers;
        If = definition.If;
        IfNot = definition.IfNot;
        IfCarrying = definition.IfCarrying;
        IfNotCarrying = definition.IfNotCarrying;
        Scope = definition.Scope;
        Once = definition.Once;
        DisabledForWorld = definition.Disabled;
        Actions = [.. definition.Actions.Select(action => new WorldAction(action))];
    }

    public bool IsDisabledFor(Session session) =>
        Scope == Scope.World
            ? DisabledForWorld
            : session.Character.DisabledInteractions.Contains(Id ?? "");

    /// <summary>
    /// Whether this interaction is currently eligible for the given player.
    /// Conditions are checked against the union of world and player flags;
    /// carrying is checked against that one player's hands, equipped or not.
    /// </summary>
    public bool IsEligible(World world, Session session)
    {
        if (IsDisabledFor(session))
        {
            return false;
        }

        if (Once && Id is not null && session.Character.FiredInteractions.Contains(Id))
        {
            return false;
        }

        foreach (var condition in If)
        {
            if (!world.HasCondition(session, condition))
            {
                return false;
            }
        }

        foreach (var condition in IfNot)
        {
            if (world.HasCondition(session, condition))
            {
                return false;
            }
        }

        foreach (var item in IfCarrying)
        {
            if (session.Character.FindItemOrEquipped(item) is null)
            {
                return false;
            }
        }

        foreach (var item in IfNotCarrying)
        {
            if (session.Character.FindItemOrEquipped(item) is not null)
            {
                return false;
            }
        }

        return true;
    }

    public bool MatchesTrigger(string command) =>
        Triggers.Any(trigger => TriggerMatcher.Matches(trigger, command));
}

